import { Group, Mesh, PlaneGeometry, BoxGeometry, Texture, DoubleSide, MeshStandardNodeMaterial } from 'three/webgpu';
import { texture, positionLocal, normalLocal } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'features-list-row';

  // ---- dimensions ----
  const ROW_WIDTH = 5.6;
  const ROW_HEIGHT = 0.9;

  // ---- depth plane 1: machined-metal card backing ----
  const backGeo = new BoxGeometry(ROW_WIDTH, ROW_HEIGHT, 0.08);
  const backMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.ink),
    roughness: 0.55,
    metalness: 0.42,
    clearcoat: 0.18,
    clearcoatRoughness: 0.4,
  });
  const backMesh = new Mesh(backGeo, backMat);
  backMesh.position.z = -0.05;
  group.add(backMesh);

  // ---- depth plane 2: tessellated parallax image plane w/ depth displacement ----
  const PLANE_W = ROW_WIDTH * 0.94;
  const PLANE_H = ROW_HEIGHT * 0.82;
  const planeGeo = new PlaneGeometry(PLANE_W, PLANE_H, 64, 64);

  const placeholderMap = new Texture();
  const placeholderDepth = new Texture();
  const mapNode = texture(placeholderMap);
  const depthNode = texture(placeholderDepth);

  const displacementStrength = 0.12;
  const displaced = positionLocal.add(normalLocal.mul(depthNode.r.mul(displacementStrength)));

  const planeMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.12,
    side: DoubleSide,
  });
  planeMat.colorNode = mapNode;
  planeMat.positionNode = displaced;

  const planeMesh = new Mesh(planeGeo, planeMat);
  planeMesh.position.z = 0.02;
  group.add(planeMesh);

  let loadedMap = null;
  let loadedDepth = null;

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedMap = tex;
    mapNode.value = tex;
    planeMat.needsUpdate = true;
  }).catch(() => {});

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      loadedDepth = tex;
      depthNode.value = tex;
      planeMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---- depth plane 3 (foreground): subtle divider ----
  const dividerGeo = new BoxGeometry(ROW_WIDTH * 0.92, 0.014, 0.02);
  const dividerMat = new THREE.MeshBasicMaterial ? null : null; // placeholder never used
  const dividerNodeMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.paper),
    roughness: 0.8,
    metalness: 0.0,
    transparent: true,
    opacity: 0.32,
  });
  const dividerMesh = new Mesh(dividerGeo, dividerNodeMat);
  dividerMesh.position.set(0, -ROW_HEIGHT * 0.46, 0.06);
  group.add(dividerMesh);

  // ---- accent edge (focus / hover indicator), foreground ----
  const accentGeo = new BoxGeometry(0.045, ROW_HEIGHT * 0.78, 0.09);
  const accentMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.1,
    roughness: 0.4,
    metalness: 0.1,
    transparent: true,
    opacity: 0.0,
  });
  const accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(-ROW_WIDTH * 0.48, 0, 0.07);
  accentMesh.scale.x = 0.001;
  group.add(accentMesh);

  // ---- node-local rim light (accent-tinted), intensity within cap ---
  const rimLight = new THREE.PointLight(new THREE.Color(colors.accent), 0.7, 4.5);
  rimLight.position.set(-1.2, 0.4, 1.4);
  group.add(rimLight);

  const fillLight = new THREE.PointLight(new THREE.Color(colors.paper), 0.35, 4.0);
  fillLight.position.set(1.5, -0.3, 1.2);
  group.add(fillLight);

  // ---- subtle cursor/camera parallax primitive (required by render mode) ----
  const primitiveResults = [];
  if (ctx.primitives && ctx.primitives['parallax-scroll']) {
    const p = ctx.primitives['parallax-scroll'](planeMesh, {
      strength: 0.06,
      trigger: 'scroll',
    });
    if (p) primitiveResults.push(p);
  }
  if (ctx.primitives && ctx.primitives['magnetic-cursor']) {
    const p2 = ctx.primitives['magnetic-cursor'](group, {
      strength: 0.03,
      trigger: 'hover',
    });
    if (p2) primitiveResults.push(p2);
  }

  // apply any explicitly configured primitives too (contract requirement)
  const configuredPrimitives = config.cinematicPrimitives ?? [];
  for (const prim of configuredPrimitives) {
    if (ctx.primitives && ctx.primitives[prim.name]) {
      const res = ctx.primitives[prim.name](group, prim.params ?? {});
      if (res) primitiveResults.push(res);
    }
  }

  // ---- motion: weighted hover lift + accent edge reveal ----
  const restY = group.position.y; // group position handled by adapter; track local offset instead
  const liftGroup = new Group();
  // move visual children under liftGroup so adapter-controlled root position stays untouched
  liftGroup.add(backMesh, planeMesh, dividerMesh, accentMesh, rimLight, fillLight);
  group.add(liftGroup);

  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(liftGroup.position, { y: 0.15, duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(accentMesh.scale, { x: 1, duration: 0.4, ease: 'power3.out' }, 0);
  hoverTl.to(accentMat, { opacity: 0.95, duration: 0.35, ease: 'power2.out' }, 0);

  let pressTween = null;

  function setHover(isHovering) {
    if (isHovering) hoverTl.play();
    else hoverTl.reverse();
  }

  function onClick() {
    if (pressTween) pressTween.kill();
    pressTween = gsap.timeline();
    pressTween.to(liftGroup.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTween.to(liftGroup.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power3.out' });
    ctx.emit('hub-features.select', { nodeId: config.id ?? 'hub-features-row' });
    ctx.emit('navigate', { to: 'hub-features' });
  }

  group.userData.handlers = {
    hover: (isHovering) => setHover(!!isHovering),
    focus: () => setHover(true),
    blur: () => setHover(false),
    click: onClick,
  };

  group.userData.cleanup = () => {
    hoverTl.kill();
    if (pressTween) pressTween.kill();
    for (const res of primitiveResults) {
      if (res && typeof res.cleanup === 'function') res.cleanup();
    }
    backGeo.dispose();
    backMat.dispose();
    planeGeo.dispose();
    planeMat.dispose();
    dividerGeo.dispose();
    dividerNodeMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
    placeholderMap.dispose();
    placeholderDepth.dispose();
    if (loadedMap) loadedMap.dispose();
    if (loadedDepth) loadedDepth.dispose();
  };

  return group;
}
